def erweitern(T):
    for t in T:
        a_de, neu_de, a_ar, neu_ar = EXP[t["id"]]
        assert a_de in t["de"], (t["id"], "de-anker")
        assert a_ar in t["ar"], (t["id"], "ar-anker")
        t["de"] = t["de"].replace(a_de, neu_de + a_de, 1)
        t["ar"] = t["ar"].replace(a_ar, neu_ar + a_ar, 1)
